def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    for r in range(h):
        marks=[c for c,v in enumerate(grid[r]) if v==6 or v==5]
        for a,b in zip(marks,marks[1:]):
            for c in range(a+1,b):
                out[r][c]=3
    for c in range(w):
        marks=[r for r in range(h) if grid[r][c]==6 or grid[r][c]==5]
        for a,b in zip(marks,marks[1:]):
            for r in range(a+1,b):
                out[r][c]=3
    return out
